// DeviceDeleteOne builds the delete of one `devices` row. Start one with
// `Graph.devices().delete_one(node)` or `delete_one_id(id)`.
pub struct DeviceDeleteOne {
	graph Graph
pub:
	data vgraph.MutationData
}

// delete_one starts the delete of the row of `node`.
pub fn (q DeviceQuery) delete_one(node DeviceNode) DeviceDeleteOne {
	return q.delete_one_id(node.device.id)
}

// delete_one_id starts the delete of the row with the key `id`.
pub fn (q DeviceQuery) delete_one_id(id string) DeviceDeleteOne {
	return DeviceDeleteOne{
		graph: q.graph
		data:  vgraph.MutationData{
			op:      .delete_one
			table:   'devices'
			row_key: id.str()
		}
	}
}

// exec deletes the row, with its join table rows, in one transaction, or
// returns a `NotFoundError`.
pub fn (b DeviceDeleteOne) exec() ! {
	if !b.graph.client.delete_one(b.data)! {
		return NotFoundError{
			table: 'devices'
		}
	}
}

// DeviceDelete builds the delete of the `devices` rows that match its conditions.
// Start one with `Graph.devices().delete()`.
pub struct DeviceDelete {
	graph Graph
pub:
	data vgraph.MutationData
}

// delete starts the delete of the rows that match the query's conditions; its
// order, limit and offset don't apply.
pub fn (q DeviceQuery) delete() DeviceDelete {
	return DeviceDelete{
		graph: q.graph
		data:  vgraph.MutationData{
			op:    .delete
			table: 'devices'
			conds: q.query.conds.clone()
		}
	}
}

// where keeps the rows that match every one of `conds`.
pub fn (b DeviceDelete) where(conds ...load.Cond) DeviceDelete {
	return DeviceDelete{
		...b
		data: b.data.with_conds(conds)
	}
}

